  if (initialPreSelection && timeZone) {
    initialPreSelection = toZonedTime(initialPreSelection, timeZone);
  }

  return {
    open: this.props.startOpen || false,
    preventFocus: false,
    inputValue: null,
    preSelection: initialPreSelection ?? boundedPreSelection,
