          hour: getHours(time),
          minute: getMinutes(time),
        });

    this.setState({
      preSelection: changedDate,
    });

    // Convert from zoned time to UTC if timezone is specified
    if (changedDate && timeZone) {
      changedDate = fromZonedTime(changedDate, timeZone);
    }

